    "title": "Zero-Shot Neural Network Evaluation With Sample-Wise Activation Patterns",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Pattern Analysis and Machine Intelligence",
