    "title": "Small-Perturbation Adversarial Example Detection via Proactive Decision Boundary Bending",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Dependable and Secure Computing",
    "year": "2026",
