    "direction": "人工智能",
    "summary": "This paper proposes ABIGX (Adversarial fault reconstruction-Based Integrated Gradient eXplanation), a unified framework for explainable fault detection and classification (FDC). ABIGX builds on the foundational principles of established fault diagnosis methods, including contribution plots (CP) and reconstruction-based contribution (RBC), while extending their applicability to general FDC models and improving fault explanation results. Central to ABIGX is the Adversarial Fault Reconstruction (AFR) method, which rethinks fault reconstruction from the perspective of adversarial attacks, introducing a novel fault index applicable to both fault detection and classification tasks. In fault detection, we theoretically bridge ABIGX with conventional fault diagnosis methods by proving that CP and RBC are the linear specifications of ABIGX. For fault classification, we address the challenge of fault class smearing, an inherent issue that can obscure accurate explanations. We demonstrate that ABIGX effectively mitigates this issue, outperforming current gradient-based explanation methods. The experiments evaluate the explanations of FDC by quantitative metrics and intuitive illustrations. The results validate the generality and accuracy of AFR, and show that ABIGX provides more comprehensive and precise explanations across various FDC models, offering a significant improvement over existing methods.",
