    "direction": "人工智能",
    "summary": "Accurate prediction of pedestrian motion is crucial for autonomous driving, particularly in path planning and collision avoidance applications. Most current methods concentrate on spatiotemporal feature parameters (e.g., velocity continuity, social force parameters, and poses) extracted from historical trajectories to model pedestrian movement. However, these methodologies fail to adequately capture pedestrian intent and do not dynamically account for behavioral heterogeneity, leading to significant discrepancies with real-world observations. To address this issue, a dynamic pedestrian intention understanding (DPIU) framework is proposed, which links future intentions to historical experiences. Grounded in cognitive decision-making mechanisms derived from human physiology, the DPIU framework is designed to predict pedestrian motion by inferring inherent movement intentions. To establish a comprehensive historical perspective, a multiscale detail feature module is employed, incorporating a time-scale-based trajectory segmentation strategy to enhance the representation of pedestrian states. Subsequently, a goal intent prediction module is introduced, employing a probabilistic model to estimate pedestrians' inclination toward the spatial scope of their intended goals. This module assesses the similarity between the current scene and historical experiences, thereby optimizing the utilization of time-fragmented information. Finally, a dynamic optimization module is developed, which superimposes intent point probabilities and applies a Bayesian-based density estimation method to ensure that the predicted outcomes closely align with real-world behaviors. Experimental evaluations on the Stanford drone drones (SDD), ETH-UCY, and ApolloScape datasets demonstrate that the proposed DPIU framework outperforms existing methods in predicting future trajectories and optimizing multimodal forecasting outcomes. The method substantially improves predictive performance in dynamic scenarios, providing a valuable tool for autonomous driving applications.",
