    "direction": "信息安全",
    "summary": "Driven by escalating threats and regulatory scrutiny, information security risk management (ISRM) is now a strategic imperative for organizations across the industrial spectrum. Although prior literature reviews offer valuable insights into ISRM subdomains, they remain fragmented and overly reliant on manual methods, limiting their scope and scalability. Additionally, only limited reviews have been able to comprehensively synthesize ISRM literature across its three foundational pillars: processes, governance, and strategy. To address this gap, we conduct a large-scale systematic literature review of 623 ISRM-related articles using a mixed-methods approach which combines natural language processing techniques with thematic analysis. We identify 22 thematic clusters and aggregate them into an integrated framework comprising three interdependent perspectives: Technical, Socio-Behavioral, and Strategic & Governance. Our integrated framework bridges disciplinary silos to inform research opportunities at the intersection of technical controls, human behavior, and strategic oversight.",
