    "direction": "人工智能",
    "summary": "The motion prediction of surrounding vehicles is crucial for autonomous driving. As it can effectively guide the planning and decision-making of the autonomous vehicle. Although many methods have been proposed to predict the future motion of vehicles, but they failed capture the essense of multitask learning for vehicle motion prediction and lacked effective semantic and interaction information fusion. In this paper, we propose a novel model, Graph Attention Transformer with Multi- Task Learning (GATran), to predict the future motion of the target vehicle by modeling motion prediction task as a multi-task learning problem of trajectory prediction and driving intention estimation. The model consists of three modules: Feature Fusion, Spatio-Temporal Interaction, and Motion Decoder. The Feature Fusion module is used to effectively fuse the semantic and dynamic information of the target vehicle. The Spatial Interaction module is used to model the interaction between vehicles. The Motion Decoder module decouples the motion prediction into multi-task learning for trajectory prediction and driving intention estimation in a parallel manner. Extensive experiments on real-world datasets, with average improvement of 50% in NGSIM and 40% in HighD, demonstrate that the proposed model achieves superior performance.",
