    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tdsc.2026.3699451",
    "direction": "信息安全",
    "summary": "To obtain the most suitable recommendation service for medical tourism, patients typically submit medical records to service providers, who perform similarity computations to recommend customized medical tourism options. To preserve data privacy, patients should upload encrypted medical records, enabling service providers to perform similarity computations on ciphertext. However, medical records are typically high-dimensional and sparse, making encrypted similarity computation less efficient and accurate. In this paper, we propose a privacy-preserving personalized medical tourism recommendation service named P3RS-MT. The proposed scheme employs weighted Tanimoto coefficient (WTC) to enable efficient and accurate similarity computations, while adopts somewhat homomorphic encryption (SHE) to safeguard medical records from exposure to service providers. Since SHE does not natively support division operations-required for WTC-we address this limitation using Newton's method for iterative approximation. Theoretical analysis and experimental evaluations show that P3RS-MT is secure, accurate and efficient.",
