    "pdf": "papers/incremental_2eeea1836af5.pdf",
    "link": "https://doi.org/10.1109/tdsc.2026.3708224",
    "direction": "信息安全",
    "summary": "Federated learning (FL) enables collaborative model training across hospitals, clinical centers, and medical devices while preserving data privacy. However, heterogeneous data characteristics—including class imbalance, limited annotations, and non-IID distributions—lead to substantial communication overhead, thereby restricting the scalability and efficiency of federated healthcare systems. To tackle the aforementioned challenges, this article introduces a federated learning algorithm that incorporates synthetic data augmentation within federated medical datasets to improve diagnostic accuracy and reduce communication overhead in distributed healthcare environments. By embedding synthetic data generation into the FL process, the proposed algorithm mitigates data heterogeneity, enhances model generalization, and reduces the number of communication rounds required for convergence under weakly supervised and imbalanced data conditions. The proposed algorithm is evaluated on two biomedical datasets—heart disease and diabetes—and demonstrates consistently superior performance over standard FL baselines in horizontal non-IID settings.",
