    "link": "https://doi.org/10.1109/tai.2026.3669876",
    "direction": "人工智能",
    "summary": "Deep learning has been widely studied to develop computer-aided diagnosis methods for autism spectrum disorder (ASD) due to abnormalities in functional connectivity (FC) caused by neural activations. However, FC dysconnectivity occur in limited regions of the brain and the intricacy of large datasets for aggrandizing generalizability and variability are also responsible for an increase in heterogeneities. Thus, the crucial challenge for a classification framework is to identify and consolidate the distinctive features that can elevate the class separation. To resolve this predicament, we propose a Dual Attention Multi-Instance Learning Framework (DAMILF) for the diagnosis of ASD and its subtypes. The DAMILF comprises four modules: i) identification of specific regions in functional magnetic resonance imaging (fMRI), (ii) patch-level attention sub-network for extracting and strengthening patch-based localized discriminatory features, (iii) attention-aware feature map for balancing the corresponding share of each patch and generating a global feature space for the whole brain, and (iv) subject-level sub-network for supplementary whole brain global feature learning and ASD-related label prediction. Our proposed DAMILF was evaluated on large-scale baseline fMRI data collected from 408 ASD and 476 typical control subjects from the Autism Brain Imaging Data Exchange (ABIDE-1) repository, and exhibited superior diagnosis performance and a better generalization ability compared with several state-of-the-art methodologies.",
