    "summary": "This paper investigates the optimal tracking control problem for multi-agent systems (MASs) subject to actuator faults by synthesizing reinforcement learning (RL) with control barrier functions (CBFs), and active fault-tolerant control (AFTC). A novel integrated framework is proposed, wherein RL is utilized to achieve optimal tracking controller, while the AFTC scheme dynamically reconfigures the control law based on real-time fault diagnostic information. To guarantee operational safety, a CBF-based safety mechanism is embedded to maintain the forward invariance of a predefined safe set, ensuring the system operates within safe boundaries despite the presence of faults and external disturbances. In contrast to conventional quadratic programming (QP)-based approaches for enforcing safety constraints, the method offers a low-complexity solution, rendering it suitable for real-time implementation in large-scale MASs. Simulation results demonstrate the effectiveness of the proposed strategy in achieving stable consensus tracking and preserving system safety under fault conditions.",
