    "link": "https://doi.org/10.1109/tkde.2026.3691368",
    "direction": "数据工程",
    "summary": "Time series anomaly detection is typically used to identify data that deviates significantly from normal data, often indicating faults or failures in the underlying system, thus facilitating system stability and safety. Most existing methods focus on detecting anomalies after they occur, while research on predicting future anomalies remains scarce. Before anomalies manifest themselves, there are often subtle precursors exhibiting slight deviations from normal behavior, with varying reaction times and intensities. Next, the setting is often characterized by a lack of labeled data, which complicates model training. To address these challenges, we propose a time series anomaly prediction framework, TAP. It can adapt flexibly to varying reaction times of anomaly precursors across different variables using a period-aware multi-scale module, and it is able to strengthen the distinction between precursors and normal sequences via a dual-branch framework that combines reconstruction and contrastive learning. The contrastive branch employs a controlled generation strategy within the multi-scale patching to produce diverse hard negative samples for precursor identification. The reconstruction branch complements this by evaluating fluctuation magnitudes to ensure sensitivity to subtle variations. We report on experiments on eight datasets from diverse domains, finding that TAP is capable of competitive or superior performance compared to baseline methods for both anomaly detection and prediction.",
