    "direction": "数据工程",
    "summary": "Recent efforts in multimodal knowledge graph completion (MKGC) have demonstrated impressive progress empowered by contrastive learning. However, a non-common sense observation shows that the simple pursuit of cross-modal consensus might degenerate MKGC performance unexpectedly, owing to the integration of untrustworthy auxiliary modalities. This behavior is herein referred to as modality degradation, which inadvertently diminishes the synergy between contrastive learning and MKGC. In this paper, we introduce a Structure-Guided Elastic Consensus Learning (SECL) framework. It captures cross-modal consensus from trustworthy multimodal entity representations for MKGC. Specifically, to reduce the semantic bias observed in CLIP-derived multimodal representations, a structure-guided multimodal representation harmonization method is introduced in SECL. With the structural context of different entities being a coordinator, this method selectively suppresses irrelevant features in CLIP-derived multimodal representations, thereby promoting their inter-modal semantic consistency. To supervise this harmonization process, an elastic contrastive learning method is presented. It alleviates the under-exploration of cross-modal consensus by steering the model optimization to prioritize aligning multimodal representations for hard entities. Extensive experiments on benchmark datasets show that SECL exhibits modality evolution instead of degradation and yields substantial improvements over state-of-the-art methods.",
