    "direction": "信息安全",
    "summary": "Backdoor attacks on deep models have received increasing attention from researchers due to their stealth and destructiveness, leading to the proposal of numerous attack methods. Among these attack approaches, clean-label attacks exhibit superior concealment and practicality because they can bypass manual checks. However, current clean-label triggers are usually independent of the original image and rely on simple patterns, making them easy to detect and recognize. To address these issues, we propose a novel clean-label backdoor attack framework that systematically decouples style and content via a style transfer network, leveraging style features as stealthy triggers to achieve semantic consistency and evade advanced defense mechanisms. Specifically, utilizing a style predictor network to achieve precise extraction and effective separation of image styles, we have carefully trained a style trigger generator that combines them with predefined style features and image content, thereby constructing style triggers highly correlated with the image. To further enhance the attack's aggressiveness and stealthiness, we introduce a consistency constraint composed of style loss and content loss, which encourages poisoned images to have a similar style to the style trigger and the same content as the clean images. Comprehensive experiments on standard benchmark datasets have demonstrated that our style backdoor attack achieves nearly perfect success rates on poisoned samples, with a minimal impact on the accuracy of benign samples, and is capable of bypassing almost all state-of-the-art backdoor defenses.",
