    "direction": "人工智能",
    "summary": "Clustering is a fundamental task in machine learning and data mining. The success of deep learning, especially deep generative models, has given birth to the next generation of clustering - deep unsupervised clustering featured by the capability of clustering large-scale and high-dimensional data. One typical example is the Gaussian mixture variational autoencoder (GMVAE), where the prior of the latent variable is a mixture of Gaussian distributions (GMM). However, the mixture number manually given in GMVAE greatly impacts on the final clustering performance and also limits the adaptation ability when new clusters come. To solve this issue, we propose an Infinite Gaussian Mixture Autoencoder (IGMVAE), which replaces the plain Gaussian prior in VAE with an infinite Gaussian mixture distribution. Our method adaptively learns the number of mixtures from data, overcoming the manual setting limitation in GMVAE, and dynamically expands clusters for novel categories. Experimental results on three datasets show that our proposed IGMVAE achieves 5.5%–14.25% higher clustering accuracy compared to GMVAE. Moreover, our model is capable of generating high-quality data in a fully unsupervised manner.",
