    "title": "Parallel Secure Pattern Matching With Differential Privacy and Consistency Checking",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Dependable and Secure Computing",
    "year": "2026",
