    "direction": "数据工程",
    "summary": "K-means is a powerful unsupervised clustering method for regularly structured data, relying fundamentally on geometric cluster centers. However, extending this paradigm to graph-structured data remains challenging. We propose ”K Graph-Centers” — a novel method that defines the graph cluster via ”graph center”, represented as an-dimensional vector minimizing the sum of weighted topological distances within its cluster. We introduce an efficient power iteration scheme to compute graph centers by: 1. diffusing affinity through normalized adjacency matrix; 2. enforcing sparsity via row-wise discretization. Cluster assignments are derived from the converged graph centers, similar with K-means. K-Graph Centers method exhibits rather lower computational complexity and fast convergence speed, compared to traditional spectral based methods. The experimental results verify its time efficiency and clustering performance in common metrics.",
