    "direction": "信息安全",
    "summary": "Emerging developments in image editing have raised substantial hurdles regarding the reliability of multimedia data, which promotes the exploration of forgery image detection. Copy move forgery, a prevalent tampering technique, is defined as duplicating one area of an image (source region) to another area of the same image (tampered region). Consequently, the source and tampered regions exhibit identical data distributions, posing a formidable obstacle to simultaneously detecting and distinguishing them. Existing discriminative methods struggle to distinguish source and tampered regions due to the absence of explicit prior constraints, especially under identical data distributions. To address this limitation, we propose a novel generative framework, PD2Net, which formulates the task as a role-constrained representation construction process guided by learnable prototypes, enabling end-to-end detection and differentiation of source and tampered regions. Specifically, two distinct prototypes are introduced as priors for the source and tampered regions, and are iteratively optimized through prototype-feature interaction to progressively refine role-constrained representations. This mechanism alleviates the difficulty caused by identical feature distributions and enables more stable distinguishment. In addition, we propose Suspect Region Selection (SS) and Suspect Region Re-identification (SR) modules to obtain the object-level refined target guided by the prototype by eliminating false positive pixels. Extensive experiments on USC-ISI, CASIA v2.0, and CoMoFoD datasets confirm the effectiveness and robustness of our proposed framework in the field of copy-move forgery image detection and distinguishment.",
