    "direction": "信息安全",
    "summary": "Photo sharing over social networks has become part of daily life. However, such practices can inadvertently lead to privacy breaches, particularly when done without the consent of unaware individuals in photos, known as the non-consensual photo sharing issue. Existing strategies, such as interactive schemes and access policy-based mechanisms, often fail to effectively determine if individuals in a photo are knowingly captured. To address this, we propose Perspicio, a new system to protect users' privacy when their images are captured unintentionally. Perspicio not only ensures heightened privacy but also accurately detect the unawareness of individuals captured in photos. This is achieved by first integrating more specific features for personal identification and introduces a dynamic weighting approach to adjust the significance of these features based on different scenarios and individual characteristics. Second, it leverages a new protocol that enhances both authorization and sharing with a higher privacy level. Finally, we conduct extensive evaluations and demonstrate that it achieves outstanding performance. Compared with the state-of-the-art in identifying unaware individuals in photos, Perspicio boosts the prediction accuracy by up to 13.2%, while speeding up the processing by 862× and 1,425× at online and offline phases, respectively.",
