    "direction": "人工智能",
    "summary": "Large language models (LLMs) have achieved remarkable performance across a wide range of downstream tasks, with parameter-efficient fine-tuning methods such as LoRA significantly reducing computational overhead. However, LLMs remain vulnerable to catastrophic forgetting when learning sequential tasks, and the rank of LoRA is typically fixed at the same value across all model layers and tasks, leaving the role of rank underexplored in continual learning. In this paper, we propose a novel parameter-efficient approach for continual learning in LLMs, which adaptively adjusts layerwise LoRA ranks to help balance the stability&#8211;plasticity trade-off. Our proposed method leverages a subspace similarity metric to evaluate the orthogonality between task-specific low-rank subspaces and thus adaptively increases the layerwise rank for each new task, thereby minimizing interference with previously learned tasks while enhancing generalization. Experimental results on standard natural language processing continual learning benchmarks and challenging mathematical benchmarks show that our method achieves comparable or superior performance in mitigating forgetting, improving task performance, and maintaining strong generalization to unseen data in a memory-efficient manner. Code is provided in the link .",
