    "direction": "信息安全",
    "summary": "Authenticated key agreement (AKA) between vehicles and roadside units (RSUs) is a fundamental component for securing Vehicular ad-hoc networks (VANETs). However, most existing AKA schemes rely on conventional cryptographic primitives, such as discrete logarithm and large integer factorization, rendering them vulnerable to emerging quantum attacks. Although several post-quantum solutions based on lattice-hard problems have been proposed, their heavy dependence on a centralized trusted authority exposes them to single-point-of-failure risks. To address these issues, we propose a decentralized authenticated key agreement scheme grounded in the security assumptions of the Ring Learning With Errors (RLWE) and Inhomogeneous Small Integer Solution (ISIS) problems. The proposed scheme achieves strong resistance against quantum adversaries while preserving the privacy of communicating entities. Furthermore, a threshold-based voting mechanism is employed to mitigate the inherent key exposure problem within network infrastructure. By distributing authentication authority across multiple edge server nodes, the scheme significantly enhances system robustness against single-node failures and collusion attacks. Comprehensive security analysis and performance evaluations demonstrate that the proposed scheme satisfies diverse security requirements with acceptable computational and communication overhead, thereby confirming its practicality for deployment in real-world VANETs environments.",
