    "link": "https://doi.org/10.1109/tdsc.2026.3698487",
    "direction": "信息安全",
    "summary": "Retrieval-Augmented Generation (RAG) services enhances LLMs by dynamically retrieving relevant information from external knowledge sources, addressing their limitations in handling up-to-date or domain-specific knowledge. Under the constraints of the cloud-native LLM service paradigm, many existing RAG systems are typically deployed in cloud environments and rely on retrieving raw information from local datasets of users or third-party knowledge providers to enhance generation. However, these cloud-based RAG services often neglect critical privacy and intellectual property concerns of the knowledge base, potentially leaking sensitive information during deployment or inference. To address these risks, we propose a privacy preserving framework (PriRAG) via proxy knowledge for cloud based RAG. The core idea is to compress the raw data of the retrieved information into proxy knowledge representations with carefully-designed privacy preservation mechanisms. We first propose a knowledge construction mechanism that aligns proxy representations with the semantic space of LLMs to preserve utility. Then we develop a query-centric knowledge representation method with a tailored training strategy to selectively exclude the irrelevant content, further reducing the exposure of privacy sensitive content. We further formulate a differential privacy enhanced collaborative inference strategy to secure the whole framework with certifiable guarantees. Extensive experiments on 7 public benchmarks and 4 LLMs show that PriRAG achieves a favorable balance between utility and privacy, significantly reducing privacy risks while maintaining high-quality generation.",
