    "link": "https://doi.org/10.1109/tdsc.2026.3695911",
    "direction": "信息安全",
    "summary": "Recent studies have proposed APT detection methods based on provenance graphs. However, existing systems face challenges due to large-scale graphs, leading to high memory consumption and limited efficiency. Many datasets provide only preprocessed data without disclosing log collection and attribute mapping, hindering reproducibility. Some approaches rely on commercial EDR or high-quality threat intelligence, limiting real world adoption. To address these limitations, this study proposes a Graph Attention Network (GAT)-based APT detection framework with spectral feature refinement. The framework uses Sysmon logs and integrates MITRE ATT&CK technique matching with open source Sysmon filtering rules to construct Rule-Filtered Provenance Graphs (RFPGs), reducing graph size while preserving security-relevant semantics. Textual and numerical attributes are encoded into unified node and edge representations to model heterogeneous system entities and interactions. A spectrally refined GAT model is then employed for malicious node detection, with an Interval Bias mechanism to adjust detection sensitivity under a controlled precision trade-off. Experimental results show that the proposed system achieves 98.25% accuracy, 90.58% precision, and a 0.36% false positive rate. Compared with a baseline model, it reduces inference time by up to 10.8% and GPU memory consumption by 11.4%. Model inference takes 0.82 seconds, while the complete pipeline requires approximately 5 seconds.",
