    "direction": "信息安全",
    "summary": "Intelligent Transport Systems (ITS) use advanced technologies to enhance safety, mobility, and traffic efficiency for drivers, passengers, and pedestrians. Vehicular Ad-hoc Networks (VANETs) are a core component of ITS, enabling real-time communication among vehicles. However, ensuring VANET security remains a critical challenge, as malicious behavior can directly impact passenger safety and system reliability. Recent studies have explored machine learning (ML)-based misbehavior detection, predominantly relying on supervised approaches that require large volumes of labeled data, which are costly and difficult to obtain in practice. Semi-supervised learning provides a practical alternative by exploiting both labeled and unlabeled data. In this work, an adaptive semi-supervised self-training framework for VANET misbehavior detection is proposed. The method incorporates an adaptive confidence thresholding mechanism and hyperparameter optimization to improve learning stability under varying data conditions. Evaluation on the VeReMi dataset demonstrates that the proposed approach, particularly with XGBoost, consistently improves accuracy, precision, recall, and F1-score across different proportions of initially unlabeled data. The results further indicate robust performance in low-label scenarios, with the most notable gains observed at moderate-to-high proportion of unlabeled data. These findings highlight the robustness and practical applicability of the proposed method for real-world vehicular security applications.",
