    "direction": "人工智能",
    "summary": "Well log instruments continuously measure multiple geophysical parameters of wellbore rocks, providing highresolution observation data for identifying subsurface lithology. Recently, lithology identification methods based on semisupervised learning and transfer learning have been investigated to address the widespread issue of label scarcity. However, these methods only account for the distribution discrepancy between wells (domains), while ignoring the data divergence within a well. This can result in inaccurate pseudo-labels within a well and erroneous label matching across wells. To cope with these challenges, we propose a dual adversarial adaptation method with dynamic labeling mechanism for semi-supervised crosswell lithology identification. Our method leverages intra-domain adversarial learning to promote fine-grained category alignment and inter-domain adversarial learning to generate domaininvariant feature representations, thereby reducing the data differences within and between wells. Additionally, our method introduces a dynamic label adjustment mechanism to optimize the selection of target pseudo-labels and source samples, thereby increasing reliable supervision information and improving the feature alignment process. Experimental results on actual well log datasets demonstrate that our method can achieve effective cross-well lithology identification when target labels are scarce.",
