    "link": "https://doi.org/10.1109/tdsc.2026.3697494",
    "direction": "信息安全",
    "summary": "Face swapping replaces the identity of a target face with that of a source face while retaining non-identity attributes, and is widely used in privacy protection scenarios. However, removing identity information makes it difficult to support sub sequent recognition tasks. Although active tracing methods can determine content ownership, techniques such as watermarking rely on external data binding, which cannot establish identity associations in the feature space nor support authorization controlled identity verification. To address this issue, we propose a key-driven Identity Protection and Secure Traceability (IPST) framework for face-swapped images, which enables identity bind ing and controlled verification without exposing visual identity. The proposed method operates as a plug-in applied to face swapping results, introducing an implicit identity association in the feature space so that the target identity participates in the generation process while remaining visually imperceptible. Specifically, IPST consists of three stages. First, an identity transfer stage aligns the generated image with the target identity in the recognition space via feature-guided perturbations. Second, an identity hiding stage performs key-controlled latent space editing to map the identity into a concealed state, ensuring that the published image cannot be directly recognized. Finally, an identity recovery stage reconstructs the target identity under authorized conditions through inverse latent manipulation, enabling identity verification using face recognition models. Experimental results demonstrate that the proposed method achieves stable identity binding while preserving visual quality, and shows strong robustness against unauthorized recovery. Moreover, the framework is model-agnostic and can be seamlessly integrated with existing face swapping systems, making it suitable for practical deployment.",
