    "direction": "数据工程",
    "summary": "In real-world information retrieval scenarios, addressing data incompleteness is crucial for providing accurate similarity scores and ensuring reliable results for downstream tasks. Previous Similarity Matrix Completion (SMC) methods aim to estimate a similarity matrix that exhibits positive semi-definiteness (PSD) from an inaccurate one. However, these methods are inadequate in cases where the initial similarity matrix$S^{0}$exhibits PSD. In this paper, we propose a novel SMC framework that simultaneously explores the symmetric, positive semi-definiteness (PSD), and low-rank properties to provide an accurate and efficient solution for similarity search tasks. Specifically, we exploit the low-rank property and introduce an efficient specialized Cholesky factorization (CF) technique into the conventional SMC framework, which is implemented via a regularizer. It improves computational efficiency by learning a smaller factorized matrix instead of the entire similarity matrix. Moreover, to enhance the optimality guarantees of SMC, we introduce a novel lower-rank matrix property and design two corresponding regularizers. Building upon these meticulous designs, our novel SMC framework, for the first time, ensures both efficiency and accuracy with theoretical guarantees. Consequently, we propose two novel algorithms, i.e., SMCFN/SMCRN, to implement the SMC framework. Theoretical analysis verifies the effectiveness and fast convergence speed of SMCFN/SMCRN. Extensive experiments on five real-world datasets validate our theoretical analysis: SMCFN/SMCRN achieves up to 42% lower RMSE (e.g., 0.34 vs. 0.59 on ImageNet) and 15% higher Recall than state-of-the-art baselines, while being the most efficient among all baseline methods.",
