    "title": "MPDA: Multimodal Prompt Decoupling Attack on the Safety Filters in Text-to-Image Models",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Dependable and Secure Computing",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "partial",
    "contentNote": "已获取机器摘要，待人工六段式总结",
    "doi": "10.1109/tdsc.2026.3696145",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tdsc.2026.3696145",
    "direction": "信息安全",
    "summary": "Text-to-image (T2I) models have been widely applied in generating high-fidelity images across various domains. However, these models may also be abused to produce Not-Safe-for-Work (NSFW) content via jailbreak attacks. Existing jailbreak methods primarily manipulate the textual prompt, leaving potential vulnerabilities in image-based inputs largely unexplored. Moreover, text-based methods face challenges in bypassing the model's safety filters. In response to these limitations, we propose the Multimodal Prompt Decoupling Attack ($\\mathsf {MPDA}$), which utilizes image modality to separate the harmful semantic components of the original unsafe prompt.$\\mathsf {MPDA}$follows three core steps: firstly, a large language model (LLM) decouples unsafe prompts into pseudo-safe prompts and harmful prompts. The former are seemingly harmless sub-prompts that can bypass filters, while the latter are sub-prompts with unsafe semantics that trigger filters. Subsequently, the LLM rewrites the harmful prompts into natural adversarial prompts to bypass safety filters, which guide the T2I model to modify the base image into an NSFW output. Finally, to ensure semantic consistency between the generated NSFW images and the original unsafe prompts, the visual language model generates image captions, providing a new pathway to guide the LLM in iterative rewriting and refining the generated content. Extensive experiments empirically demonstrate that$\\mathsf {MPDA}$outperforms the baseline methods in two attack scenarios across Stable Diffusion 3.5 and three commercial models: CogView, Tongyiwanxiang, and Midjourney. Specifically, in the pornographic content attack scenario with Midjourney as the victim model, our method has a 29% higher bypass rate than the previous method, thereby providing robust empirical evidence supporting the effectiveness and generalizability of$\\mathsf {MPDA}$. Disclaimer: This paper contains content that readers may find offensive, distressing, or upsetting. Reader discretion is advised.",
