    "direction": "人工智能",
    "summary": "Hypergraph neural network (HGNN) excels at representing intricate relationships within non-Euclidean infinitedimensional spaces. However, traditional hypergraph frameworks are grounded in homophily assumption and encounter challenges in handling heterophily problem in semi-supervised classification tasks. To tackle this problem, this paper first analyzes the underlying reasons that limit homophily-based hypergraphs, and proposes a heterophily-based dynamic structure. Under this structure, a Heterophily-based Dynamic HGNN (HDHGNN) is then proposed for semi-supervised classification. HDHGNN decomposes the hypergraph’s triple pattern iterative process into two causally related sub-procedures, within which attention mechanisms are incorporated to enable dynamic interactions. To evaluate the effectiveness of HDHGNN, a relative entropybased heterophily degree evaluation method is first introduced, followed by comprehensive fault classification experiments on two real-world flight datasets from rotary-wing and fixed-wing unmanned aerial vehicles, with comparisons against 11 state-of-the-art methods.",
