    "title": "Similarity-guided state attention for visual reinforcement learning",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "partial",
    "contentNote": "已获取机器摘要，待人工六段式总结",
