    "direction": "人工智能",
    "summary": "Conventional neural networks’ reliance on pairwise connections limits their ability to model the modular higher-order interactions inherent in biological neural systems. The stability analysis and control of large-scale networks that integrate these higher-order interactions with fractional-order dynamics and multiple time delays present a significant challenge due to analytical intractability. This study establishes a theoretical and computational framework for a large-scale fractional-order neural network model featuring modular triplet clusters. Analytical criteria for stability and Hopf bifurcation are derived. To address the control challenge, a reinforcement learning framework is implemented for the adaptive tuning of higher-order coupling strength to suppress destabilizing oscillations. Numerical results quantify the profound impact of system parameters on stability while demonstrating the reinforcement learning controller’s ability to maintain stability where traditional methods fail. By adaptively tuning the coupling strength without any prior knowledge of the system model, the proposed approach effectively suppresses oscillations, showcasing a advantage over model-based controllers for such high-dimensional, analytically intractable systems.",
