    "link": "https://doi.org/10.1109/tai.2026.3678540",
    "direction": "人工智能",
    "summary": "The task of target speaker extraction (TSE) involves isolating a specific speaker’s voice from a mixture of multiple audio sources. Most existing TSE methods primarily optimize the reconstruction quality of the extracted waveform while overlooking essential cues contained in the reference audio. Moreover, traditional TSE networks lack an interactive learning mechanism that jointly models mixed and reference embeddings, often leading to speaker confusion, particularly when there is a notable mismatch between the reference and target audio. To overcome these challenges, we propose a novel end-to-end dual-attention-based target speaker extraction (DATSE) network that explicitly addresses speaker confusion. DATSE employs an attention-weighted multi-scale speech encoder that adaptively emphasizes features at different temporal resolutions. In addition, it introduces an attention-based speaker aggregation module within the auxiliary speaker recognition network, which effectively integrates speaker-specific information and leverages mixed-audio cues to refine target speaker embeddings. Experimental results on the WSJ0-2mix-extr dataset show that, the proposed method not only achieves competitive performance across multiple metrics but also significantly reduces speaker confusion under various disturbances such as noise and reverberation, thereby effectively lowering the overall confusion rate.",
    "question": "待人工补全。",
