    "direction": "数据工程",
    "summary": "Radius-bounded$k$-core queries (RB-$k$-core queries) in geo-social networks aim to identify all$k$-cores containing a given query vertex$q$, where all vertices in each$k$-core fall within a circle defined by a specified query radius$r$. These queries are widely used in applications such as team formation and event organization. However, specifying query parameters$k$and$r$can be challenging for users without domain expertise, often resulting in misaligned query results. Specifically, some expected vertices may be missing, while unexpected vertices may appear in the results. To address this issue, we investigate the problem ofexploringoptimalrefinedparametersforexpected(EOPE) andunexpected(EOPU) results in RB-$k$-core queries. The goal is to explore optimal parameters that ensure the expected vertex$\\omega$(or unexpected vertex$\\psi$) and query vertex$q$appear (or do not appear) in the same RB-$k$-core. For the EOPE problem, we first propose two baseline algorithms:PriorityRandHybridR. To improve efficiency, we develop two more advanced algorithms:PriorityKandHybridK. Additionally, we introduce a novel index calledHCR-Tree, based on hierarchical coreness of vertices and R-Tree, to enhance exploration efficiency. For the EOPU problem, we begin with a basic solution (BS) and then design the segmentation algorithmSA, which incorporates effective pruning and termination strategies. We conduct extensive experiments on five real-world geo-social network datasets. The results demonstrate that our proposed algorithms effectively explore optimal parameters. Among them,HybridKproves most effective for EOPE, whileSAperforms best for EOPU. Furthermore,HCR-Treeoutperforms R-Tree for both EOPE and EOPU problems.",
