    "pdf": "papers/incremental_f00f5f9773b9.pdf",
    "link": "https://doi.org/10.1109/tdsc.2026.3697897",
    "direction": "信息安全",
    "summary": "Collaborative inference (CI) improves computational efficiency for edge devices by transmitting intermediate features to cloud models. However, this process inevitably exposes feature representations to model inversion attacks (MIAs), enabling unauthorized data reconstruction. Despite extensive research, there is no established criterion for assessing the difficulty of MIA implementation, leaving a fundamental question unanswered: What factors truly and verifiably determine the attack's success in CI? Moreover, existing defences lack the theoretical foundation described above, making it challenging to regulate feature information effectively while ensuring privacy and minimizing computational overhead. These shortcomings introduce three key challenges: theoretical gap, methodological limitation, and practical constraint. To overcome these challenges, we propose the first theoretical criterion to assess MIA difficulty in CI, identifying mutual information, entropy, and effective information volume as key influencing factors. We use the Mutual Information Neural Estimator to quantify mutual information, a key metric for assessing the privacy-preserving effect of defences, and to validate the proposed criterion. Building on this insight, we propose SiftFunnel, a privacy-preserving framework to resist MIA while maintaining usability. Specifically, we incorporate linear and nonlinear correlation constraints alongside label smoothing to suppress redundant information transmission, effectively balancing privacy and usability. To enhance deployability, the edge model adopts a funnel-shaped structure with attention mechanisms, strengthening privacy while reducing computational and storage burdens. Experiments show that, compared to state-of-the-art defence, SiftFunnel increases reconstruction error by ∼30%, lowers mutual and effective information metrics by ≥50%, and reduces edge burdens by almost 20×, while maintaining comparable usability.",
