    "method": "框架先在整理后的网络安全语料上对 LLaMA-2-7B 进行继续预训练，得到领域模型 Certibase，再用认证对齐的指令问答进行监督微调，并采用 4-bit NF4 量化的 QLoRA 降低显存和训练成本。部署上提供 beginner、intermediate、advanced 三个解释深度层级；评测比较多种结构化 prompt，以及 Chain-of-Thought、Logic CoT、System 2 Attention、Contrastive CoT 和 Self-consistency CoT 等推理策略。",
    "experiments": "实验使用四个认证领域的数据集：训练集共 3,194 个样本、验证集 158 个样本，测试集共 215 道题。Certibase 在无提示条件下平均准确率为 51.5%，最佳结构化提示提升至 64.1%；在推理策略比较中，CertiGuard 使用 Self-consistency CoT 的平均准确率最高，为 86.5%，其次为 Contrastive CoT 的 84.7% 和 Logic CoT 的 83.4%。论文同时报告了 95% Wilson 置信区间，并指出小规模测试集使这些提升应被视为探索性结果。",
