    "summary": "研究带时滞的切换非线性系统的事件触发脉冲控制（ETIC）：提出模态依赖事件触发机制（MDETM），用 Lyapunov–Razumikhin 与平均驻留时间方法给出指数稳定判据并排除 Zeno 现象，再把结果用于切换神经网络的同步与图像加密。",
    "question": "切换与时滞并存时，延迟状态可能来自当前子系统不同的一段历史区间，切换也可能发生在下一次脉冲之前，使稳定性分析与控制综合变得困难；同时希望只在触发时刻施加脉冲输入，从而降低控制器到执行器的通信负担。",
    "method": "构造模态依赖事件触发机制，把与初始历史信息相关的指数衰减项纳入触发条件，以处理时滞与切换耦合的影响；基于 Lyapunov–Razumikhin 方法与平均驻留时间技术建立充分判据，保证系统指数稳定并排除 Zeno 行为，同时给出事件间隔的显式下界。将该理论应用于切换神经网络（SNN）的指数同步，触发机制与脉冲控制增益的设计条件写成线性矩阵不等式（LMI）；随后用同步系统驱动图像加密。",
