    "direction": "信息安全",
    "summary": "这是 IEEE Security & Privacy「Privacy as Contextual Integrity」特刊的客座编辑导言：以情境完整性（CI）为隐私理论基础，介绍三篇把 CI 应用于监管、AI 治理与语音隐私的前沿论文，强调 CI 需要在应用中持续被压力测试与更新。",
    "question": "主流隐私定义（如“告知-同意”）难以应对强大数字技术与 AI 带来的新型威胁，导致监管效果不彰；CI 把隐私理解为“信息流是否符合情境规范”，跨学科影响力渐增，并进入 AI 与大模型智能体系统的设计与工程实践。把 CI 翻译到不同学科语言时需要比“静态理论直接投影”更多的工作。",
